cd /workspace/app; cat > /tmp/testspawn.mjs <<'EOF'
import { spawn } from 'node:child_process';
const child = spawn('pnpm', ['nx','serve','app','--configuration=instance','--port=40461','--host=0.0.0.0','--allowedHosts=app.urbo.localhost'], {
  cwd: '/workspace/app',
  stdio: ['ignore','pipe','pipe'],
  env: {...process.env, PWD:'/workspace/app'},
});
child.stdout.on('data', d=>process.stdout.write(d));
child.stderr.on('data', d=>process.stderr.write(d));
child.on('exit',(c,s)=>{console.log('CHILD EXIT', c, s); process.exit(0);});
setTimeout(()=>{console.log('TIMEOUT alive'); process.exit(124);}, 120000);
EOF
node /tmp/testspawn.mjs 2>&1 | tail -15; echo "exit=${PIPESTATUS[0]}"
